from collections import defaultdict
def solve(g):
    h,w=len(g),len(g[0])
    diag=defaultdict(lambda: defaultdict(int))
    for r in range(3,h):
        for c in range(3,w):
            if g[r][c]: diag[r+c][g[r][c]]+=1
    o=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if o[r][c]==0:
                if r<2 or c<2: o[r][c]=1
                elif r==2 or c==2: o[r][c]=4
                else:
                    d=diag[r+c]
                    o[r][c]=max(d,key=d.get)
    return o
# verify on demo
